# RWDM_MIRROR: Mirror: a mirror-image copy across a line (vertical plane) or a horizontal plane. The script rwdm_mirror_script.txt is generated by rwdm_gen.py (the closed forms are in that file); every case moves each Point object
# from its closed-form image E_k to the origin and lists it: the app prints a coordinate within 1e-9 of an integer as that integer, so a
# passing case means every image lies within 1e-9 of the textbook formula (a residual of 1e-6 would read 1e-06; RWDM_*_sensitivity checks that).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_MIRROR_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_mirror_script.txt" 2>&1)" || { echo "$RWDM_MIRROR_OUT" | tail -40; echo "FAIL RWDM_MIRROR_run: script exited non-zero"; fail=1; RWDM_MIRROR_OUT=""; }
else
  RWDM_MIRROR_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_mirror_script.txt" 2>&1)" || { echo "$RWDM_MIRROR_OUT" | tail -40; echo "FAIL RWDM_MIRROR_run: script exited non-zero"; fail=1; RWDM_MIRROR_OUT=""; }
fi
rwdm_mirror_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_MIRROR_OUT"; }
# rwdm_mirror_check NAME N DESC: the case listed exactly N points and every one of them is "0,0,0" (the residual to the closed form)
rwdm_mirror_check() {
  local blk npts zeros; blk="$(rwdm_mirror_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ]; then echo "ok   RWDM_MIRROR_$1: $3 ($2 points, every one within 1e-9 of the closed form)"
  else echo "FAIL RWDM_MIRROR_$1: $3 (listed $npts points, $zeros at residual 0; expected $2 and $2)"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -12 | sed 's/^/     residual: /'; fi
}
rwdm_mirror_check diag 8 "Mirror across the line (0,0)-(1,1) (plane x = y, copy) swaps x and y of the copies"
rwdm_mirror_check vert 8 "Mirror across the line x = 2 (picked (2,0)-(2,5)) maps x to 4 - x"
rwdm_mirror_check move 4 "Mirror with Copy=No moves the originals across the plane x = 2 (4 points, no copies)"
rwdm_mirror_check plane_z 8 "In the Front viewport a mirror line along x at z = 2 is the horizontal plane z = 2: z maps to 4 - z"
rwdm_mirror_check xaxis 8 "Mirror with the XAxis option mirrors across the CPlane X axis (y -> -y)"
# negative control: the same harness must SEE a 1e-6 error (point moved 1e-6 off its expected image reads 1e-06, not 0)
rwdm_mirror_sens() {
  local blk; blk="$(rwdm_mirror_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RWDM_MIRROR_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RWDM_MIRROR_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rwdm_mirror_sens
